CREATE TABLE reading_bookmark (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,work_id UUID NOT NULL,edition_id UUID NOT NULL,chapter_id UUID NOT NULL,locator_kind VARCHAR(32) NOT NULL,locator_value VARCHAR(1024) NOT NULL,content_version VARCHAR(256),label VARCHAR(256),created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,FOREIGN KEY(work_id) REFERENCES reading_work(id) ON DELETE CASCADE,FOREIGN KEY(edition_id) REFERENCES reading_edition(id) ON DELETE CASCADE,FOREIGN KEY(chapter_id) REFERENCES reading_chapter(id) ON DELETE CASCADE,UNIQUE(owner_id,chapter_id,locator_kind,locator_value));
